package wgmodern;
import java.util.*;import net.minecraft.core.*;import net.minecraft.gametest.framework.*;import net.minecraft.world.item.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.ChestBlockEntity;import net.minecraft.nbt.CompoundTag;import net.minecraftforge.gametest.*;
@GameTestHolder("witchinggadgets") @PrefixGameTestTemplate(false)
public class BlastServerTests {
 @GameTest(template="empty") public static void furnaceRequiresExactStructureAndRestoresOriginalBlocks(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(3,2,3));for(int i=0;i<27;i++)l.setBlock(p.offset(BlastFurnace.offset(i)),BlastFurnace.original(i),3);h.assertTrue(BlastFurnace.valid(l,p),"Exact original nether-brick/obsidian/soulsand/stairs/lava structure validates");var corner=p.offset(BlastFurnace.offset(18));l.setBlockAndUpdate(corner,l.getBlockState(corner).setValue(StairBlock.FACING,Direction.WEST));h.assertTrue(!BlastFurnace.valid(l,p),"Outward top corner rejected");l.setBlockAndUpdate(corner,BlastFurnace.original(18));BlastFurnace.form(l,p,Direction.NORTH);for(int i=0;i<27;i++){var q=p.offset(BlastFurnace.offset(i));h.assertTrue(l.getBlockState(q).getValue(BlastFurnace.PART)==i&&((BlastFurnace.Tile)l.getBlockEntity(q)).master()==l.getBlockEntity(p),"Every part resolves the bottom owner");}var lost=p.offset(1,1,0);l.destroyBlock(lost,false);for(int i=0;i<27;i++){var q=p.offset(BlastFurnace.offset(i));if(!q.equals(lost))h.assertTrue(l.getBlockState(q).is(BlastFurnace.original(i).getBlock()),"Unforming restores block "+i);}h.assertTrue(l.isEmptyBlock(lost),"Broken location stays removed");pass(h);}
 @GameTest(template="empty") public static void furnaceTriplesClustersAndHonorsBellowsAndQueueSave(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(3,2,3));BlastFurnace.form(l,p,Direction.NORTH);var t=(BlastFurnace.Tile)l.getBlockEntity(p);var input=new ItemStack(tc4revival.content.TCItems.cluster(tc4revival.content.ClusterType.IRON),2);t.offer(input);input.shrink(1);h.assertTrue(t.inputs.get(0).getCount()==2,"Queue owns an independent copy");t.duration=440;h.assertTrue(t.time()==440,"Original base time");t.speedup=600;h.assertTrue(t.time()==220,"Vis or essentia halves duration");for(var f:Direction.Plane.HORIZONTAL)l.setBlockAndUpdate(p.relative(f,2),tc4revival.content.TCArcane.BELLOWS.get().defaultBlockState().setValue(tc4revival.content.BellowsBlock.FACING,f.getOpposite()));h.assertTrue(t.bellows()==4&&t.time()==60,"Each of four correctly facing bellows subtracts forty ticks");var saved=t.saveWithoutMetadata();var copy=new BlastFurnace.Tile(p,l.getBlockState(p));copy.load(saved);h.assertTrue(copy.inputs.get(0).getCount()==2&&copy.speedup==600&&copy.owner.equals(p),"Queue and progress persist");var output=p.north(2).above();l.setBlockAndUpdate(output,Blocks.CHEST.defaultBlockState());var chest=(ChestBlockEntity)l.getBlockEntity(output);for(int i=0;i<123;i++)BlastFurnace.Tile.tick(l,p,l.getBlockState(p),t);h.assertTrue(chest.countItem(Items.IRON_INGOT)==6&&t.inputs.isEmpty(),"Exactly two clusters become six ingots via sided output");pass(h);}
 @GameTest(template="empty") public static void furnaceLavaConsumesValidItemsRejectsOthersAndKeepsNbtDistinct(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(3,2,3));BlastFurnace.form(l,p,Direction.EAST);var t=(BlastFurnace.Tile)l.getBlockEntity(p);var lava=p.above(2);var valid=new net.minecraft.world.entity.item.ItemEntity(l,lava.getX()+.5,lava.getY()+.2,lava.getZ()+.5,new ItemStack(tc4revival.content.TCItems.cluster(tc4revival.content.ClusterType.GOLD),3));Content.BLAST.get().entityInside(l.getBlockState(lava),l,lava,valid);h.assertTrue(valid.isRemoved()&&t.inputs.size()==1&&t.inputs.get(0).getCount()==3,"Lava accepts the entire valid stack");var invalid=new net.minecraft.world.entity.item.ItemEntity(l,lava.getX()+.5,lava.getY()+.2,lava.getZ()+.5,new ItemStack(Items.DIRT,7));Content.BLAST.get().entityInside(l.getBlockState(lava),l,lava,invalid);h.assertTrue(invalid.isRemoved()&&t.inputs.size()==1,"Unsupported input is destroyed in lava without output");var named=t.inputs.get(0).copy();named.setHoverName(net.minecraft.network.chat.Component.literal("Distinct"));t.offer(named);h.assertTrue(t.inputs.size()==2,"Distinct NBT cannot be merged and erased");h.assertTrue(l.getBlockState(lava).getCollisionShape(l,lava).isEmpty(),"Top lava has no collision");pass(h);}
 private static void pass(GameTestHelper h){com.mojang.logging.LogUtils.getLogger().info("WITCHINGGADGETS_TEST_PASS {}",Thread.currentThread().getStackTrace()[2].getMethodName());h.succeed();}
}
